{"function":"() => {
const parse=c=>{const m=c.match(/[\d.]+/g);return m?m.map(Number):null};
const lum=([r,g,b])=>{const f=v=>{v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4)};return 0.2126*f(r)+0.7152*f(g)+0.0722*f(b)};
const bgOf=el=>{let e=el;while(e){const c=getComputedStyle(e).backgroundColor;const p=parse(c);if(p&&(p.length<4||p[3]>0))return c;e=e.parentElement}return 'rgb(255,255,255)'};
const out=[];
const walker=document.createTreeWalker(document.querySelector('#root'),NodeFilter.SHOW_TEXT);
const seen=new Set();
while(walker.nextNode()){const t=walker.currentNode;if(!t.textContent.trim())continue;const el=t.parentElement;if(seen.has(el))continue;seen.add(el);const cs=getComputedStyle(el);const r=el.getBoundingClientRect();if(r.width===0)continue;const fg=parse(cs.color),bg=parse(bgOf(el));const L1=lum(fg),L2=lum(bg);const ratio=(Math.max(L1,L2)+0.05)/(Math.min(L1,L2)+0.05);
out.push([el.tagName+'.'+el.className, t.textContent.trim().slice(0,30), cs.fontSize, cs.fontWeight, cs.color, bgOf(el), ratio.toFixed(2), cs.opacity])}
// placeholders
document.querySelectorAll('input[placeholder]').forEach(i=>{const cs=getComputedStyle(i,'::placeholder');out.push(['placeholder#'+i.id,i.placeholder,cs.fontSize,cs.color,cs.opacity,bgOf(i)])});
return out.map(a=>a.join(' | ')).join('\n')}"}

